export function validateRepositoryLockInvalidValidationEvidence(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "state")) fail(contract, `${path}.state`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "state": {
          if (item !== "repository_lock_invalid") fail(contract, `${path}.state`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.state`, "expected string");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateRepositoryPathExistsRequirement(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "path")) fail(contract, `${path}.path`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "kind": {
          if (item !== "path_exists") fail(contract, `${path}.kind`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.kind`, "expected string");
          break;
        }
        case "path": {
          if (typeof item !== "string") fail(contract, `${path}.path`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.path`, "must contain at least 1 characters");
          if ((item as string).length > 240) fail(contract, `${path}.path`, "must contain at most 240 characters");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateRepositorySourceAuthority(value: unknown, path: string, contract: string, refStack: Set<string>): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "subject_instance_id")) fail(contract, `${path}.subject_instance_id`, "missing required property");
  if (!Object.hasOwn(record, "source_snapshot")) fail(contract, `${path}.source_snapshot`, "missing required property");
  if (!Object.hasOwn(record, "authority_id")) fail(contract, `${path}.authority_id`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "authority_id": {
          if (typeof item !== "string") fail(contract, `${path}.authority_id`, "expected string");
          break;
        }
        case "source_snapshot": {
          validateReference("PlanSnapshotEvidence", validatePlanSnapshotEvidence, item, `${path}.source_snapshot`, contract, refStack);
          break;
        }
        case "subject_instance_id": {
          if (typeof item !== "string") fail(contract, `${path}.subject_instance_id`, "expected string");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateRepositoryStartedEvent(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "sequence")) fail(contract, `${path}.sequence`, "missing required property");
  if (!Object.hasOwn(record, "fleet_run_id")) fail(contract, `${path}.fleet_run_id`, "missing required property");
  if (!Object.hasOwn(record, "event_type")) fail(contract, `${path}.event_type`, "missing required property");
  if (!Object.hasOwn(record, "repository_id")) fail(contract, `${path}.repository_id`, "missing required property");
  if (!Object.hasOwn(record, "operation_id")) fail(contract, `${path}.operation_id`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "event_type": {
          if (item !== "REPOSITORY_STARTED") fail(contract, `${path}.event_type`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.event_type`, "expected string");
          break;
        }
        case "fleet_run_id": {
          if (typeof item !== "string") fail(contract, `${path}.fleet_run_id`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.fleet_run_id`, "must contain at least 1 characters");
          break;
        }
        case "generated_at": {
          if (typeof item !== "string") fail(contract, `${path}.generated_at`, "expected string");
          if (Number.isNaN(Date.parse(item as string))) fail(contract, `${path}.generated_at`, "expected date-time string");
          break;
        }
        case "operation_id": {
          if (typeof item !== "string") fail(contract, `${path}.operation_id`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.operation_id`, "must contain at least 1 characters");
          break;
        }
        case "repository_id": {
          if (typeof item !== "string") fail(contract, `${path}.repository_id`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.repository_id`, "must contain at least 1 characters");
          break;
        }
        case "sequence": {
          if (typeof item !== "number" || !Number.isFinite(item)) fail(contract, `${path}.sequence`, "expected finite number");
          if (!Number.isInteger(item)) fail(contract, `${path}.sequence`, "expected integer");
          if ((item as number) < 1.0) fail(contract, `${path}.sequence`, "must be >= 1.0");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}
